begin;
create sequence if not exists public.dc_issue_serial;
create table if not exists public.dc_issues (
 id uuid primary key default gen_random_uuid(), number text unique not null,
 group_id text not null,item_id text not null,label text not null,location text not null,area text not null,
 status text not null default 'Open' check(status in ('Open','In progress','Awaiting verification','Closed')),
 first_record text not null references public.dc_checklist_records(id),last_record text not null,
 reported_at timestamptz not null,last_seen timestamptz not null,
 original_note text not null,photos jsonb not null default '[]',closed_at timestamptz
);
create unique index if not exists dc_one_active_issue on public.dc_issues(group_id,item_id) where status<>'Closed';
create table if not exists public.dc_issue_events (
 id uuid primary key,issue_id uuid not null references public.dc_issues(id),action text not null,
 actor_id uuid,actor_name text not null,at timestamptz not null default now(),details jsonb not null default '{}',
 record_id text references public.dc_checklist_records(id)
);
create index if not exists dc_issue_events_by_issue on public.dc_issue_events(issue_id,at);
alter table public.dc_issues enable row level security;
alter table public.dc_issue_events enable row level security;
revoke all on public.dc_issues,public.dc_issue_events from anon,authenticated;
grant select on public.dc_issues,public.dc_issue_events to authenticated;
create or replace function public.dc_issue_access() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.dc_checklist_members where user_id=auth.uid() and active and (role='admin' or not password_change_required));
$$;
revoke all on function public.dc_issue_access() from public,anon;
grant execute on function public.dc_issue_access() to authenticated;
create policy dc_issues_team_read on public.dc_issues for select to authenticated using(public.dc_issue_access());
create policy dc_issue_events_team_read on public.dc_issue_events for select to authenticated using(public.dc_issue_access());
-- Reconstruct legacy history without changing any original inspection.
do $$ declare r record;a record;t public.dc_issues;v jsonb;n bigint;stamp timestamptz; begin
 if not exists(select 1 from public.dc_issues) then
 for r in select * from public.dc_checklist_records order by created_at,id loop
 v:=r.payload::jsonb;stamp:=to_timestamp(r.created_at/1000.0);
 if v->>'kind'='resolve' then
 update public.dc_issues set status='Closed',closed_at=stamp where item_id=v->>'item' and status<>'Closed';
 elsif v->>'kind'='inspection' then
 for a in select key,value from jsonb_each(v->'answers') loop
 if a.value->>'status'='FAULTY' then
 select * into t from public.dc_issues where group_id=v->>'group' and item_id=a.key and status<>'Closed';
 if not found then
 n:=nextval('public.dc_issue_serial');
 insert into public.dc_issues(number,group_id,item_id,label,location,area,first_record,last_record,reported_at,last_seen,original_note,photos)
 values(to_char(stamp at time zone 'Asia/Riyadh','YYMMDD')||'-'||lpad(n::text,greatest(3,length(n::text)),'0'),v->>'group',a.key,coalesce((select x->>'label' from jsonb_array_elements(coalesce(v->'items','[]')) x where x->>'id'=a.key limit 1),a.key),coalesce(v->>'location',''),coalesce(v->>'areaName',v->>'area',''),r.id,r.id,stamp,stamp,coalesce(a.value->>'note',''),coalesce(a.value->'photos','[]')) returning * into t;
 insert into public.dc_issue_events values(gen_random_uuid(),t.id,'Reported',r.created_by,coalesce(v->>'name','Legacy record'),stamp,jsonb_build_object('note',a.value->>'note'),r.id);
 else update public.dc_issues set last_seen=stamp,last_record=r.id where id=t.id;end if;
 elsif a.value->>'status'='Normal' then update public.dc_issues set status='Closed',closed_at=stamp where group_id=v->>'group' and item_id=a.key and status<>'Closed';
 end if;end loop;end if;end loop;
 end if;end $$;
