insert into public.dc_issue_events(id,issue_id,action,actor_name,at,details)
select gen_random_uuid(),id,'Legacy closure','Historical checklist',closed_at,jsonb_build_object('note','Closed under the previous workflow before this upgrade. Original records retained.') from public.dc_issues where status='Closed';
create or replace function public.dc_ticket_inspection() returns trigger language plpgsql security definer set search_path='' as $$
declare v jsonb:=new.payload::jsonb;a record;t public.dc_issues;n bigint;stamp timestamptz:=now();answer jsonb;
begin
 if v->>'kind'='resolve' then raise exception 'Use the issue workflow to complete and verify repairs';end if;
 if v->>'kind'<>'inspection' then return new;end if;
 perform pg_advisory_xact_lock(7210241);
 if exists(select 1 from public.dc_issues where group_id=v->>'group' and status<>'Closed' and not(coalesce(v->'answers','{}') ? item_id)) then raise exception 'Complete all items with outstanding issues';end if;
 for a in select key,value from jsonb_each(v->'answers') loop
 select * into t from public.dc_issues where group_id=v->>'group' and item_id=a.key and status<>'Closed' for update;
 if found then
 if a.value->>'status' is distinct from 'FAULTY' then raise exception 'Outstanding issue % must remain Faulty until verified and closed',t.number;end if;
 answer:=a.value||jsonb_build_object('issueId',t.id,'issueNumber',t.number,'issueStatus',t.status,'note',concat_ws(' | ',nullif(a.value->>'note',''),'Outstanding issue: '||t.number||' — '||t.status));
 v:=jsonb_set(v,array['answers',a.key],answer);
 update public.dc_issues set last_record=new.id,last_seen=stamp where id=t.id;
 insert into public.dc_issue_events values(gen_random_uuid(),t.id,'Checklist observation',new.created_by,coalesce(v->>'name',''),stamp,jsonb_build_object('note',a.value->>'note'),new.id);
 elsif a.value->>'status'='FAULTY' then
 n:=nextval('public.dc_issue_serial');
 insert into public.dc_issues(number,group_id,item_id,label,location,area,first_record,last_record,reported_at,last_seen,original_note,photos)
 values(to_char(stamp at time zone 'Asia/Riyadh','YYMMDD')||'-'||lpad(n::text,greatest(3,length(n::text)),'0'),v->>'group',a.key,coalesce((select x->>'label' from jsonb_array_elements(v->'items') x where x->>'id'=a.key limit 1),a.key),coalesce(v->>'location',''),coalesce(v->>'areaName',''),new.id,new.id,stamp,stamp,coalesce(a.value->>'note',''),coalesce(a.value->'photos','[]')) returning * into t;
 v:=jsonb_set(v,array['answers',a.key],a.value||jsonb_build_object('issueId',t.id,'issueNumber',t.number,'issueStatus','Open','note',concat_ws(' | ',a.value->>'note','Issue: '||t.number)));
 insert into public.dc_issue_events values(gen_random_uuid(),t.id,'Reported',new.created_by,coalesce(v->>'name',''),stamp,jsonb_build_object('note',a.value->>'note'),new.id);
 end if;end loop;
 new.payload:=v::text;return new;
end $$;
-- Deferred ticket references allow a BEFORE INSERT trigger to enrich the checklist atomically.
alter table public.dc_issues alter constraint dc_issues_first_record_fkey deferrable initially deferred;
alter table public.dc_issue_events alter constraint dc_issue_events_record_id_fkey deferrable initially deferred;
create trigger dc_zz_ticket_inspection before insert on public.dc_checklist_records for each row execute function public.dc_ticket_inspection();
create or replace function public.dc_issue_transition(p_issue uuid,p_action text,p_details jsonb,p_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare m public.dc_checklist_members;t public.dc_issues;v jsonb;next_status text;photo text;record_id text:=p_request::text;previous public.dc_issue_events;
begin
 select * into m from public.dc_checklist_members where user_id=auth.uid();
 if not public.dc_issue_access() then raise exception 'Active checklist membership required';end if;
 perform pg_advisory_xact_lock(7210241);
 select * into previous from public.dc_issue_events where id=p_request;
 if found then
 if previous.issue_id<>p_issue or previous.actor_id<>auth.uid() or previous.action<>p_action then raise exception 'Request reference already used';end if;
 return jsonb_build_object('recordId',previous.record_id,'saved',true);end if;
 select * into t from public.dc_issues where id=p_issue for update;
 if not found then raise exception 'Issue not found';end if;
 if p_action='Start work' and t.status='Open' then next_status:='In progress';
 elsif p_action='Complete repair' and t.status='In progress' then
 if nullif(trim(p_details->>'rootCause'),'') is null or nullif(trim(p_details->>'repair'),'') is null or jsonb_typeof(p_details->'photos') is distinct from 'array' or jsonb_array_length(p_details->'photos') not between 1 and 3 or coalesce(p_details->>'furtherAction','') not in ('Yes','No') then raise exception 'Complete root cause, repair details, follow-up choice and after-repair photos';end if;
 if p_details->>'furtherAction'='Yes' and (nullif(trim(p_details->>'followUp'),'') is null or nullif(trim(p_details->>'responsible'),'') is null or coalesce(p_details->>'due','')!~'^\d{4}-\d{2}-\d{2}$') then raise exception 'Add follow-up action, responsible person and target date';end if;
 for photo in select jsonb_array_elements_text(p_details->'photos') loop
 if not exists(select 1 from public.dc_inspection_photos where id::text=photo and user_id=auth.uid() and group_id=t.group_id and item_id=t.item_id) then raise exception 'Invalid repair photo';end if;end loop;
 next_status:='Awaiting verification';
 elsif p_action in ('Verify and close','Return for further work') and t.status='Awaiting verification' then
 if m.role not in ('admin','supervisor') then raise exception 'Supervisor or Admin verification required';end if;
 if nullif(trim(p_details->>'verification'),'') is null then raise exception 'Add verification comments';end if;
 next_status:=case when p_action='Verify and close' then 'Closed' else 'In progress' end;
 else raise exception 'Issue status changed. Refresh and try again';end if;
 if p_action='Start work' then p_details:='{}'::jsonb;elsif p_action in ('Verify and close','Return for further work') then p_details:=jsonb_build_object('verification',p_details->>'verification');end if;
 p_details:=p_details||jsonb_build_object('completedBy',coalesce(nullif(m.full_name,''),m.email),'dateTime',now());
 v:=jsonb_build_object('id',record_id,'kind','issue_event','issueId',t.id,'issueNumber',t.number,'action',p_action,'status',next_status,'group',t.group_id,'item',t.item_id,'label',t.label,'area',concat_ws(' · ',t.location,t.area),'originalFault',t.original_note,'originalInspection',t.first_record,'name',coalesce(nullif(m.full_name,''),m.email),'date',to_char(now() at time zone 'Asia/Riyadh','YYYY-MM-DD'),'createdAt',floor(extract(epoch from now())*1000),'details',p_details);
 insert into public.dc_checklist_records(id,created_at,payload,created_by) values(record_id,(v->>'createdAt')::bigint,v::text,auth.uid());
 insert into public.dc_issue_events values(p_request,t.id,p_action,auth.uid(),v->>'name',now(),p_details,record_id);
 update public.dc_issues set status=next_status,closed_at=case when next_status='Closed' then now() else null end where id=t.id;
 return jsonb_build_object('recordId',record_id,'saved',true);
end $$;
revoke all on function public.dc_issue_transition(uuid,text,jsonb,uuid) from public,anon;
grant execute on function public.dc_issue_transition(uuid,text,jsonb,uuid) to authenticated;
revoke all on function public.dc_ticket_inspection() from public,anon,authenticated;
-- Permit reuse of the original fault photos only for the same active issue and item.
create or replace function public.dc_require_fault_photos() returns trigger language plpgsql set search_path='' as $$
declare a record;photo text;v jsonb:=new.payload::jsonb;
begin
if v->>'kind'<>'inspection' or new.created_by is null then return new;end if;
for a in select key,value from jsonb_each(v->'answers') loop
 if a.value->>'status'='FAULTY' and (jsonb_typeof(a.value->'photos') is distinct from 'array' or jsonb_array_length(a.value->'photos')=0) then raise exception 'Every faulty item requires a saved photo';end if;
 if a.value ? 'photos' then
 if jsonb_typeof(a.value->'photos')<>'array' or jsonb_array_length(a.value->'photos')>3 then raise exception 'Invalid photo list';end if;
 for photo in select jsonb_array_elements_text(a.value->'photos') loop
 if not exists(select 1 from public.dc_inspection_photos p where p.id::text=photo and p.group_id=v->>'group' and p.item_id=a.key and (p.user_id=new.created_by or exists(select 1 from public.dc_issues t where t.group_id=p.group_id and t.item_id=p.item_id and t.status<>'Closed' and t.photos ? photo))) then raise exception 'Photo does not belong to this inspector or active issue';end if;
 end loop;end if;end loop;return new;end $$;
-- Team can preview repair photos once they are submitted in an issue event.
drop policy dc_photos_read on public.dc_inspection_photos;
create policy dc_photos_read on public.dc_inspection_photos for select to authenticated using(public.dc_issue_access() and (user_id=auth.uid() or exists(select 1 from public.dc_checklist_records r where r.payload::jsonb @> jsonb_build_object('answers',jsonb_build_object(dc_inspection_photos.item_id,jsonb_build_object('photos',jsonb_build_array(dc_inspection_photos.id::text))))) or exists(select 1 from public.dc_issue_events e where e.details->'photos' ? dc_inspection_photos.id::text)));
commit;
